// Validate factory webhook input + derive artifact metadata
//
// Expected input: { pattern: { action, occurrence_count, success_rate, ... } }
// Output: enriched payload pro Anthropic prompt

const body = $input.first().json.body || $input.first().json;
const pattern = body.pattern;

if (!pattern || !pattern.action) {
  throw new Error('pattern.action required');
}

// Derive skill identity from action name
// e.g., action 'blue_green_switch_committed' → skill 'aisha-blue-green-switch'
const slug = String(pattern.action)
  .toLowerCase()
  .replace(/_committed$|_succeeded$|_completed$/, '')
  .replace(/^aisha[_-]/, '')
  .replace(/_/g, '-')
  .replace(/[^a-z0-9-]/g, '');

const skillName = `aisha-${slug}`;
const skillPath = `.claude/skills/${skillName}/SKILL.md`;

return [{
  json: {
    skill_name: skillName,
    skill_path: skillPath,
    pattern,
    occurrence_count: pattern.occurrence_count || 0,
    success_rate: pattern.success_rate || 0,
    requested_at: new Date().toISOString(),
  },
}];

