// Extract rendered content + validate
const response = $input.first().json;
const content = response.content?.[0]?.text;

if (!content) {
  throw new Error('No content from Anthropic response');
}

// Basic validation
const hasFrontmatter = /^---\n[\s\S]*?\nname:\s*\S+/m.test(content);
const hasDescription = /^description:\s*.{50,}/m.test(content);
const hasSections = (content.match(/^##\s+/gm) || []).length;

const validation = {
  has_frontmatter: hasFrontmatter,
  has_description: hasDescription,
  section_count: hasSections,
  passed: hasFrontmatter && hasDescription && hasSections >= 3,
};

return [{
  json: {
    ...$('Validate + Derive Identity').item.json,
    rendered_content: content,
    validation,
  },
}];

